import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_M 128
#define TILE_N 64
#define TILE_K 16
#define THREADS_X 16
#define THREADS_Y 16
__global__ void conv2d_kernel(const float* __restrict__ input,
                              const float* __restrict__ weight,
                              const float* __restrict__ bias,
                              float* __restrict__ output,
                              int N, int C_in, int H_in, int W_in,
                              int C_out, int H_out, int W_out,
                              int K, int stride, int pad,
                              int Kdim, int S) {
    __shared__ float As[2][TILE_K][TILE_M];
    __shared__ float Bs[2][TILE_K][TILE_N + 1];
    __shared__ int sh_n[TILE_M];
    __shared__ int sh_pix[TILE_M];
    __shared__ int sh_hbase[TILE_M];
    __shared__ int sh_wbase[TILE_M];
    extern __shared__ int sh_kdec[];
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * THREADS_X + tx;
    const int m0 = blockIdx.y * TILE_M;
    const int n0 = blockIdx.x * TILE_N;
    const int M = N * S;
    const int KK = K * K;
    float acc[8][4];
    #pragma unroll
    for (int im = 0; im < 8; ++im) {
        #pragma unroll
        for (int jn = 0; jn < 4; ++jn) {
            int c_out = n0 + tx * 4 + jn;
            acc[im][jn] = (c_out < C_out) ? bias[c_out] : 0.0f;
        }
    }
    // Cache the im2col row decode once per CTA and reuse it for every K-tile.
    for (int ml = tid; ml < TILE_M; ml += THREADS_X * THREADS_Y) {
        int m = m0 + ml;
        if (m < M) {
            int n = m / S;
            int pix = m - n * S;
            int h_out = pix / W_out;
            int w_out = pix - h_out * W_out;
            sh_n[ml] = n;
            sh_pix[ml] = pix;
            sh_hbase[ml] = h_out * stride - pad;
            sh_wbase[ml] = w_out * stride - pad;
        } else {
            sh_n[ml] = 0;
            sh_pix[ml] = 0;
            sh_hbase[ml] = -1000000;
            sh_wbase[ml] = -1000000;
        }
    }
    __syncthreads();
    for (int kg = tid; kg < Kdim; kg += THREADS_X * THREADS_Y) {
        int c = kg / KK;
        int rem = kg - c * KK;
        int kh = rem / K;
        int kw = rem - kh * K;
        sh_kdec[kg] = c;
        sh_kdec[Kdim + kg] = kh;
        sh_kdec[2 * Kdim + kg] = kw;
    }
    __syncthreads();
    // Software-pipelined double buffering: prefetch stage 0.
    for (int i = tid; i < TILE_K * TILE_M; i += THREADS_X * THREADS_Y) {
        int kl = i / TILE_M;
        int ml = i % TILE_M;
        int kg = kl;
        int m = m0 + ml;
        float v = 0.0f;
        if (kg < Kdim && m < M) {
            int c = sh_kdec[kg];
            int kh = sh_kdec[Kdim + kg];
            int kw = sh_kdec[2 * Kdim + kg];
            int h_in = sh_hbase[ml] + kh;
            int w_in = sh_wbase[ml] + kw;
            if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                v = input[((size_t)sh_n[ml] * C_in + c) * H_in * W_in + (size_t)h_in * W_in + w_in];
            }
        }
        As[0][kl][ml] = v;
    }
    for (int i = tid; i < TILE_K * TILE_N; i += THREADS_X * THREADS_Y) {
        int nl = i / TILE_K;
        int kl = i % TILE_K;
        int c_out = n0 + nl;
        int kg = kl;
        float v = 0.0f;
        if (c_out < C_out && kg < Kdim) {
            v = weight[(size_t)c_out * Kdim + kg];
        }
        Bs[0][kl][nl] = v;
    }
    __syncthreads();
    int stage = 0;
    for (int k0 = 0; k0 < Kdim; k0 += TILE_K) {
        const int nxt = stage ^ 1;
        const int knext = k0 + TILE_K;
        // Prefetch the next K-tile into the idle buffer while computing on the current one.
        if (knext < Kdim) {
            for (int i = tid; i < TILE_K * TILE_M; i += THREADS_X * THREADS_Y) {
                int kl = i / TILE_M;
                int ml = i % TILE_M;
                int kg = knext + kl;
                int m = m0 + ml;
                float v = 0.0f;
                if (kg < Kdim && m < M) {
                    int c = sh_kdec[kg];
                    int kh = sh_kdec[Kdim + kg];
                    int kw = sh_kdec[2 * Kdim + kg];
                    int h_in = sh_hbase[ml] + kh;
                    int w_in = sh_wbase[ml] + kw;
                    if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                        v = input[((size_t)sh_n[ml] * C_in + c) * H_in * W_in + (size_t)h_in * W_in + w_in];
                    }
                }
                As[nxt][kl][ml] = v;
            }
            for (int i = tid; i < TILE_K * TILE_N; i += THREADS_X * THREADS_Y) {
                int nl = i / TILE_K;
                int kl = i % TILE_K;
                int c_out = n0 + nl;
                int kg = knext + kl;
                float v = 0.0f;
                if (c_out < C_out && kg < Kdim) {
                    v = weight[(size_t)c_out * Kdim + kg];
                }
                Bs[nxt][kl][nl] = v;
            }
        }
        #pragma unroll
        for (int kk = 0; kk < TILE_K; ++kk) {
            float a_frag[8];
            float b_frag[4];
            #pragma unroll
            for (int im = 0; im < 8; ++im) {
                a_frag[im] = As[stage][kk][ty * 8 + im];
            }
            #pragma unroll
            for (int jn = 0; jn < 4; ++jn) {
                b_frag[jn] = Bs[stage][kk][tx * 4 + jn];
            }
            #pragma unroll
            for (int im = 0; im < 8; ++im) {
                #pragma unroll
                for (int jn = 0; jn < 4; ++jn) {
                    acc[im][jn] = fmaf(a_frag[im], b_frag[jn], acc[im][jn]);
                }
            }
        }
        __syncthreads();
        stage = nxt;
    }
    #pragma unroll
    for (int im = 0; im < 8; ++im) {
        int ml = ty * 8 + im;
        int m = m0 + ml;
        if (m >= M) continue;
        int n = sh_n[ml];
        int pix = sh_pix[ml];
        #pragma unroll
        for (int jn = 0; jn < 4; ++jn) {
            int c_out = n0 + tx * 4 + jn;
            if (c_out < C_out) {
                output[(size_t)n * C_out * S + (size_t)c_out * S + pix] = acc[im][jn];
            }
        }
    }
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t pad) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat, "float tensors required");
    TORCH_CHECK(weight.size(2) == weight.size(3), "square kernels required");
    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int C_out = weight.size(0);
    int K = weight.size(2);
    int H_out = (H_in + 2 * pad - K) / stride + 1;
    int W_out = (W_in + 2 * pad - K) / stride + 1;
    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());
    int S = H_out * W_out;
    int M = N * S;
    int Kdim = C_in * K * K;
    dim3 threads(THREADS_X, THREADS_Y);
    dim3 blocks((C_out + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M);
    conv2d_kernel<<<blocks, threads, (size_t)3 * Kdim * sizeof(int)>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        K, (int)stride, (int)pad,
        Kdim, S);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
'''

cpp_src = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int64_t stride, int64_t pad);"

_conv_module = load_inline(
    name="conv2d_custom_cuda",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        return _conv_module.conv2d_forward(
            x.contiguous(),
            self.conv1.weight.contiguous(),
            self.conv1.bias.contiguous(),
            self.conv1.stride[0],
            self.conv1.padding[0],
        )

